// GENERATED by scripts/sync-shared.mjs from hotel-clash-api/engine — do not edit here.
// Read-only analysis of a game state: daily costs, price guidance, goals and
// tips. The simulation itself uses the same formulas (dailyCosts,
// roomPricePoint, upgradeCost), so what the dashboard shows is exactly what the
// server charges and simulates. Nothing here mutates the state.
import { dpow } from './math.js';
import { ROOM_TYPES, FACILITY_TYPES, ACHIEVEMENTS, LEVELS, ROOM_UNLOCKS, CAMPAIGN_UNLOCKS, FACILITY_UNLOCK_PRICES, WAGE_GROWTH_PER_LEVEL, PROFIT_TAX, POLICY_COSTS, DEBT, FACILITY_SERVICE, DEFAULT_SEATS, PRICE_SENSITIVITY, CAMPAIGNS, INSURANCE_PLANS, SCALE_UPKEEP, PROPERTY_TAX_RATE, STAFF_NEEDS, ROOMS_PER_PLOT, PLOT_PRICES, ACQUISITION } from './data.js';

const sum = (list, fn) => list.reduce((t, x) => t + fn(x), 0);
const avg = (list, fn) => (list.length ? sum(list, fn) / list.length : 0);

/** What the hotel pays every day (charged in tick.js dailyFinances). */
export function dailyCosts(S) {
  const payroll = Math.round(S.staff.reduce((t, e) => t + e.salary, 0) * wageFactor(S));
  const baseUpkeep = S.rooms.reduce((t, r) => {
    const rt = ROOM_TYPES.find((x) => x.type === r.type);
    return t + (rt ? rt.upkeep : 0);
  }, 0);
  const roomUpkeep = Math.round(baseUpkeep * scaleFactor(S));
  const facilityUpkeep = S.facilities.reduce((t, f) => t + f.upkeep, 0);
  const policyCosts = policyCost(S);
  const insurance = insurancePremium(S);
  const propertyTax = propertyTaxFor(S);
  return { payroll, roomUpkeep, facilityUpkeep, policyCosts, insurance, propertyTax, total: payroll + roomUpkeep + facilityUpkeep + policyCosts + insurance + propertyTax };
}

/** Room upkeep multiplier: big hotels are harder to run (×1 up to 30 rooms). */
export const scaleFactor = (S) => 1 + Math.max(0, (S.rooms || []).length - SCALE_UPKEEP.freeRooms) * SCALE_UPKEEP.perRoom;

/**
 * Core staffing: for each need (housekeeping, front desk, …) how many the
 * hotel has and needs, and `service` — the weighted coverage from 0 to 1.
 */
export function staffing(S) {
  const rooms = (S.rooms || []).length;
  let service = 0;
  const needs = STAFF_NEEDS.map((n) => {
    const need = rooms <= 4 || rooms < (n.minRooms || 0) ? 0 : Math.ceil(rooms / n.roomsEach);
    const have = (S.staff || []).filter((e) => n.roles.includes(e.role)).length;
    const coverage = need ? Math.min(1, have / need) : 1;
    service += coverage * n.weight;
    return { id: n.id, label: n.label, roles: n.roles, have, need, coverage };
  });
  return { needs, service: Math.round(service * 1000) / 1000 };
}

/** Daily property tax: 0.1% of the hotel's value. */
export const propertyTaxFor = (S) => Math.round(hotelValue(S) * PROPERTY_TAX_RATE);

/** Daily cost of the active policies (one policy, or all when `key` is omitted). */
export function policyCost(S, key) {
  const guests = (S.guests || []).length;
  let total = 0;
  for (const [k, c] of Object.entries(POLICY_COSTS)) {
    if (key ? k !== key : !(S.policies && S.policies[k])) continue;
    total += c.perDay + c.perGuest * guests;
  }
  return total;
}

/**
 * The going rate guests compare a room against: competitors in a similar
 * price band, weighted by reputation and occupancy (used by guest booking).
 */
export function roomPricePoint(S, basePrice, rep) {
  let pricePoint = basePrice;
  let weighted = 0;
  let totalWeight = 0;
  for (const c of S.competitors) {
    if (c.avgRoomPrice >= basePrice * 0.6 && c.avgRoomPrice <= basePrice * 1.4) {
      const w = (c.reputation / Math.max(1, rep) + (c.occupancyRate || 0.5)) / 2;
      weighted += c.avgRoomPrice * w;
      totalWeight += w;
    }
  }
  if (totalWeight > 0) pricePoint = weighted / totalWeight;
  return pricePoint;
}

/** Most a guest will pay before bookings drop (used by guest booking). */
export function priceThreshold(pricePoint, sensitivity, rep, tolerance) {
  return pricePoint * (1 + sensitivity * (dpow(rep, 1.6) / 4.5)) * tolerance;
}

/**
 * The stay a guest expects from a hotel with this rating: 2.4 at 1★, 3.2 at
 * 3★, 4.0 at 5★. At checkout the rating moves by (happiness − expectation) × 0.1.
 */
export const guestExpectation = (reputation) => 2 + reputation * 0.4;

/** Facilities each guest type enjoys (raises their booking chance). */
export const GUEST_LIKES = {
  Business: ['Business Center', 'Conference Room', 'Restaurant', 'Gym', 'Bar', 'Spa', 'Cigar Lounge', 'Wine Cellar'],
  Family: ['Pool', 'Kids Club', 'Restaurant', 'Movie Theater', 'Gift Shop', 'Infinity Pool'],
  Leisure: ['Spa', 'Pool', 'Bar', 'Restaurant', 'Gym', 'Nightclub', 'Casino', 'Wine Cellar', 'Premium Spa', 'Infinity Pool'],
};

/**
 * Cost to raise a room's quality by one: 600 · 1.6^quality, more for bigger
 * room types (× √(build cost / $10k), so a Penthouse costs ×3.2); null at max.
 */
export function upgradeCost(room) {
  if (room.quality >= 5) return null;
  const rt = ROOM_TYPES.find((x) => x.type === room.type);
  const typeFactor = rt ? Math.max(1, Math.sqrt(rt.baseCost / 10000)) : 1;
  return Math.floor(600 * dpow(1.6, room.quality) * typeFactor);
}

/** Price guidance for one room type for an average guest. */
export function priceGuide(S, type) {
  const rt = ROOM_TYPES.find((r) => r.type === type);
  if (!rt) return null;
  const rep = Math.min(5, Math.max(1, S.reputation || 3));
  const market = roomPricePoint(S, rt.basePrice, rep);
  const ceiling = Math.round(priceThreshold(market, 0.5, rep, 1.15));
  return { market: Math.round(market), sweet: Math.round(ceiling * 0.9), ceiling };
}

/** Dashboard numbers: yesterday's results and today's running costs. */
export function economics(S) {
  const rooms = S.rooms || [];
  const usable = rooms.filter((r) => !r.underMaintenance);
  const occupied = usable.filter((r) => r.occupied);
  const costs = dailyCosts(S);
  const lastRevenue = (S.stats && S.stats.lastDayRevenue) || 0;
  return {
    payroll: costs.payroll,
    roomUpkeep: costs.roomUpkeep,
    facilityUpkeep: costs.facilityUpkeep,
    policyCosts: costs.policyCosts,
    insurance: costs.insurance,
    propertyTax: costs.propertyTax,
    scaleFactor: scaleFactor(S),
    expenses: costs.total,
    roomIncome: sum(occupied, (r) => r.price),
    lastRevenue,
    lastRoomIncome: (S.stats && S.stats.lastDayRoomIncome) || 0,
    lastFacilityIncome: (S.stats && S.stats.lastDayFacilityIncome) || 0,
    lastIngredients: (S.stats && S.stats.lastDayFacilityCogs) || 0,
    lastTax: (S.stats && S.stats.lastDayTax) || 0,
    lastProfit: lastRevenue - costs.total - ((S.stats && S.stats.lastDayFacilityCogs) || 0) - ((S.stats && S.stats.lastDayTax) || 0),
    occupancy: usable.length ? occupied.length / usable.length : 0,
    occupiedRooms: occupied.length,
    usableRooms: usable.length,
    roomQuality: avg(rooms, (r) => r.quality),
    staffHappiness: avg(S.staff || [], (e) => e.happiness),
    guestHappiness: avg(S.guests || [], (g) => g.happiness),
  };
}

// ---------------------------------------------------------------- progression

/** What the hotel is worth: rooms (more with quality), facilities (more with level), rating. */
export function hotelValue(S) {
  let v = (S.reputation || 0) * 5000;
  for (const r of S.rooms || []) {
    const rt = ROOM_TYPES.find((x) => x.type === r.type);
    if (rt) v += rt.baseCost * (0.6 + 0.1 * r.quality);
  }
  if (S.land && S.land.paid) v += S.land.paid * 0.5;
  for (const f of S.facilities || []) {
    if (f.name === 'Lobby') continue;
    const ft = FACILITY_TYPES.find((x) => x.type === f.name);
    if (ft) v += ft.baseCost * (0.5 + 0.1 * f.level);
  }
  return Math.round(v);
}

// ---------------------------------------------------------------- land & acquisitions

/** Plots owned. Hotels from before land existed keep what their rooms need. */
export const plotsOwned = (S) => (S.land && S.land.plots) || Math.max(1, Math.ceil((S.rooms || []).length / ROOMS_PER_PLOT));

/** Most rooms the hotel's land can hold. */
export const roomCapacity = (S) => plotsOwned(S) * ROOMS_PER_PLOT;

/** Price of the next plot of land. */
export function nextPlotPrice(S) {
  const n = plotsOwned(S); // buying plot n+1
  if (n - 1 < PLOT_PRICES.length) return PLOT_PRICES[n - 1];
  return PLOT_PRICES[PLOT_PRICES.length - 1] * 2 ** (n - PLOT_PRICES.length);
}

/** What a rival hotel would cost to buy, and whether it's struggling. */
export function acquisitionOffer(S, c) {
  const distressed = c.occupancyRate < ACQUISITION.distressedBelowOccupancy;
  const health = (0.5 + c.occupancyRate) * (0.6 + (c.reputation || 0) / 5);
  const price = Math.round((c.rooms * ACQUISITION.perRoom * health * (distressed ? 1 - ACQUISITION.distressDiscount : 1)) / 1000) * 1000;
  const locked = (S.hotelLevel || 1) < ACQUISITION.unlockLevel;
  const lastRivals = (S.competitors || []).length <= ACQUISITION.minRivals;
  return { price, distressed, locked, lastRivals, unlockLevel: ACQUISITION.unlockLevel };
}

/** Highest level a hotel of this value has earned. */
export function levelForValue(value) {
  let level = 1;
  for (const l of LEVELS) if (value >= l.value) level = l.level;
  return level;
}

/** Level needed to build a facility type (cheaper ones unlock first). */
export function facilityUnlockLevel(type) {
  const ft = FACILITY_TYPES.find((x) => x.type === type);
  if (!ft) return 99;
  return FACILITY_UNLOCK_PRICES.find((t) => ft.baseCost <= t.maxCost).level;
}

/** Level needed for a room type / facility / campaign. */
export function unlockLevel(kind, id) {
  if (kind === 'room') return ROOM_UNLOCKS[id] || 1;
  if (kind === 'campaign') return CAMPAIGN_UNLOCKS[id] || 1;
  if (kind === 'facility') return facilityUnlockLevel(id);
  return 1;
}

/** Everything that unlocks exactly at a level (for the level-up screen). */
export function unlocksAt(level) {
  const out = [];
  for (const [t, l] of Object.entries(ROOM_UNLOCKS)) if (l === level) out.push(`${t} rooms`);
  for (const ft of FACILITY_TYPES) if (facilityUnlockLevel(ft.type) === level) out.push(ft.type);
  for (const [id, l] of Object.entries(CAMPAIGN_UNLOCKS)) if (l === level) out.push(`${CAMPAIGNS_LABEL[id] || id} campaign`);
  return out;
}
const CAMPAIGNS_LABEL = { local: 'Local Advertising', social: 'Social Media', discount: 'Discount Promotion', luxury: 'Luxury Package', competitive: 'Competitive Marketing' };

/** Progress towards the next level, by hotel value. */
export function levelProgress(S) {
  const level = S.hotelLevel || 1;
  const value = hotelValue(S);
  const next = LEVELS.find((l) => l.level === level + 1);
  if (!next) return { level, value, max: true, progress: 1, unlocks: [] };
  const floor = (LEVELS.find((l) => l.level === level) || LEVELS[0]).value;
  const progress = Math.max(0, Math.min(1, (value - floor) / (next.value - floor)));
  return { level, value, next: next.level, threshold: next.value, bonus: next.bonus, progress, unlocks: unlocksAt(next.level) };
}

/** Wages rise as the hotel grows (×1.04 per level). */
export const wageFactor = (S) => 1 + WAGE_GROWTH_PER_LEVEL * ((S.hotelLevel || 1) - 1);

/** Tax on one day's profit: 10% above $1k, 25% above $10k. */
export function profitTax(profit) {
  let tax = 0;
  for (let i = 0; i < PROFIT_TAX.length; i++) {
    const { above, rate } = PROFIT_TAX[i];
    const cap = PROFIT_TAX[i + 1] ? PROFIT_TAX[i + 1].above : Infinity;
    if (profit > above) tax += (Math.min(profit, cap) - above) * rate;
  }
  return Math.round(tax);
}

const ACHIEVEMENT_PROGRESS = {
  first_guest: (S) => [S.guests.length > 0 ? 1 : 0, 1],
  five_rooms: (S) => [S.rooms.length, 5],
  high_rating: (S) => [S.reputation, 4.8],
  profitable: (S) => [(S.stats && S.stats.lastDayRevenue) || 0, 5000],
  full_house: (S) => [S.rooms.filter((r) => r.occupied).length, S.rooms.length || 1],
  staff_five: (S) => [S.staff.length, 5],
  facility_all: (S) => [
    FACILITY_TYPES.filter((t) => S.facilities.some((f) => f.name === t.type)).length,
    FACILITY_TYPES.length,
  ],
  market_leader: (S) => [S.marketShare, 50],
  competitor_crusher: (S) => [
    S.competitors.filter((c) => c.reputation < S.reputation).length,
    S.competitors.length || 1,
  ],
  week_survivor: (S) => [S.day, 7],
  big_spender: (S) => [S.money, 25000],
  guest_whisperer: (S) => [S.totalGuestsServed, 50],
};

/** Locked achievements, closest to completion first. */
export function nextAchievements(S, limit = 3) {
  const unlocked = new Set(S.achievements || []);
  return ACHIEVEMENTS.filter((a) => !unlocked.has(a.id) && ACHIEVEMENT_PROGRESS[a.id])
    .map((a) => {
      const [have, need] = ACHIEVEMENT_PROGRESS[a.id](S);
      return { ...a, have, need, progress: Math.max(0, Math.min(0.99, have / need)) };
    })
    .sort((x, y) => y.progress - x.progress)
    .slice(0, limit);
}

/**
 * Short, prioritised tips about what to do next. Each tip may carry a `tab`
 * the dashboard links to. Heuristics only — they never act on their own.
 */
export function advice(S) {
  const e = economics(S);
  const tips = [];
  const cheapestRoom = Math.min(...ROOM_TYPES.map((r) => r.baseCost));
  const paidFacilities = (S.facilities || []).filter((f) => f.name !== 'Lobby');

  if (S.money < 0) {
    const d = debtStatus(S);
    tips.push({
      level: 'danger',
      tab: 'finance',
      text: d.repoTarget && d.repoIn != null
        ? `$${Math.round(d.debt).toLocaleString()} in debt: the bank seizes your ${d.repoTarget.name} in ${d.repoIn} day${d.repoIn === 1 ? '' : 's'}. Cut costs or raise prices now.`
        : `You're $${Math.round(-S.money).toLocaleString()} in debt (−$${d.interest}/day interest). Cut costs or raise prices now.`,
    });
  } else if (e.lastRevenue > 0 && e.lastProfit < 0) {
    // FIX: this used to say "or trim staff" — new players fired their only
    // receptionist, bookings collapsed and they went bankrupt.
    const loss = Math.round(-e.lastProfit);
    const perRoom = Math.max(20, (S.rooms.length ? S.rooms.reduce((t, r) => t + r.price, 0) / S.rooms.length : 80) * 0.8 - 12);
    const rooms = Math.ceil(loss / perRoom);
    const runway = S.money > 0 ? Math.floor(S.money / loss) : 0;
    tips.push({
      level: runway && runway < 30 ? 'danger' : 'warn',
      tab: 'rooms',
      text: `Losing $${loss.toLocaleString()}/day${runway ? ` — in debt in ${runway} day${runway === 1 ? '' : 's'} at this rate` : ''}. Build about ${rooms} more room${rooms === 1 ? '' : 's'} or raise prices to break even. Keep your staff: without them guests stop booking.`,
    });
  }
  if (insurancePlan(S) === 'none' && (S.day >= 120 || S.rooms.length >= 8)) {
    tips.push({ level: 'warn', tab: 'finance', text: 'You have no insurance. Fires, floods and inspections get bigger after day 200 — one can cost more than your savings.' });
  }
  const reserve = insuranceCap(S) ?? insuranceCap(S, 'basic');
  if (S.money >= 0 && S.money < reserve && S.day > 10) {
    tips.push({ level: 'info', tab: 'finance', text: `Keep about $${reserve.toLocaleString('en-US')} in reserve for emergencies.` });
  }
  if (e.usableRooms > 0 && e.occupancy >= 0.9 && e.lastProfit < 0 && S.day > 3) {
    tips.push({ level: 'danger', tab: 'rooms', text: "You're fully booked but losing money: your prices are too low. Raise them (Rooms → Pricing → Best price) or cut costs." });
  }
  if (e.usableRooms > 0 && e.occupancy < 0.4 && S.day > 3) {
    tips.push({ level: 'warn', tab: 'marketing', text: `Only ${Math.round(e.occupancy * 100)}% of rooms are booked. Run a marketing campaign or lower prices.` });
  }
  if (e.usableRooms > 0 && e.occupancy >= 0.9 && S.money >= cheapestRoom) {
    tips.push({ level: 'good', tab: 'rooms', text: 'Fully booked! Build more rooms or raise prices to earn more.' });
  }
  // Ratings settle around 1.5★ for quality-1 rooms, 3★ at 2, 4★ at 3, 5★ at 5.
  const basic = (S.rooms || []).filter((r) => r.quality < 3);
  if (basic.length && S.day > 1) {
    const cost = basic.reduce((t, r) => t + (upgradeCost(r) || 0), 0);
    const poor = basic.some((r) => r.quality < 2);
    tips.push({
      level: poor ? 'warn' : 'info',
      tab: 'rooms',
      text: poor
        ? `Quality-1 rooms drag your rating down. Upgrade ${basic.length} room${basic.length === 1 ? '' : 's'} for $${cost.toLocaleString('en-US')}.`
        : `Guests expect more as your rating grows. Upgrading ${basic.length} room${basic.length === 1 ? '' : 's'} (${'$'}${cost.toLocaleString('en-US')}) moves you toward 4★.`,
    });
  }
  if ((S.staff || []).length && e.staffHappiness < 3) {
    tips.push({ level: 'warn', tab: 'staff', text: `Staff morale is low (${e.staffHappiness.toFixed(1)}/5). Train them to keep service quality up.` });
  }
  if (e.usableRooms && (S.staff || []).length && e.usableRooms / S.staff.length > 4) {
    tips.push({ level: 'info', tab: 'staff', text: 'Your staff is stretched thin. Hire more people to keep guests happy.' });
  }
  if (!paidFacilities.length && S.money >= 15000) {
    tips.push({ level: 'info', tab: 'facilities', text: 'Build a facility (Restaurant, Bar, Spa…) — guests spend extra there every day.' });
  }

  if (!tips.length) {
    tips.push({ level: 'good', tab: null, text: 'Your hotel is running smoothly. Keep growing!' });
  }
  return tips.slice(0, 4);
}

export const SEASONS = {
  spring: { label: 'Spring', hint: 'Balanced demand; outdoor facilities are popular.' },
  summer: { label: 'Summer', hint: 'Peak season: families and tourists, pools in demand.' },
  autumn: { label: 'Autumn', hint: 'Business travelers; conference rooms pay off.' },
  winter: { label: 'Winter', hint: 'Fewer bookings; spas and indoor amenities shine.' },
};

/** Days until the next season (seasons are 90 days, see engine seasonFor). */
export function daysToNextSeason(day) {
  return 90 - (day % 90);
}

// ---------------------------------------------------------------- facilities
// One model used by the daily simulation (tick.js) and the Facilities screen.

/** What a facility sells and for how much (the player's prices, else suggested). */
export function facilityOffer(f) {
  const svc = FACILITY_SERVICE[f.name] || {};
  if (svc.menu) {
    return {
      kind: 'menu',
      orders: svc.orders || 1,
      items: svc.menu.map((i) => ({ ...i, base: i.price, price: (f.prices && f.prices[i.id]) || i.price })),
    };
  }
  const ft = FACILITY_TYPES.find((x) => x.type === f.name);
  const base = ft ? ft.incomePerGuest : 0;
  return { kind: 'fee', orders: 1, items: [{ id: 'fee', name: 'Entry fee', cost: 0, base, price: f.fee || base }] };
}

/** Average price against the suggested price (1 = normal, 1.5 = 50% dearer). */
export function priceRatio(offer) {
  const items = offer.items.filter((i) => i.base > 0);
  return items.length ? items.reduce((t, i) => t + i.price / i.base, 0) / items.length : 1;
}

/** Seats per day: seats per level × level, ±20–30% for the skill of its own staff. */
export function facilityCapacity(S, f) {
  const ft = FACILITY_TYPES.find((x) => x.type === f.name);
  const svc = FACILITY_SERVICE[f.name] || {};
  const roles = new Set(((ft && ft.requiredStaff) || []).map((r) => r.role));
  const crew = S.staff.filter((s) => roles.has(s.role));
  const skill = crew.length ? crew.reduce((t, s) => t + s.skill, 0) / crew.length : 2.5;
  return Math.max(1, Math.round((svc.seats || DEFAULT_SEATS) * f.level * (0.8 + skill * 0.1)));
}

/** How price affects demand for one type of visitor (higher levels justify higher prices). */
function priceAppeal(offer, level, visitorType) {
  const allowance = 0.1 * (level - 1);
  const sensitivity = PRICE_SENSITIVITY[visitorType] ?? 1;
  return Math.min(1.25, Math.max(0.05, 1 - (priceRatio(offer) - 1 - allowance) * sensitivity));
}

/** Chance that one staying guest visits this facility today. */
export function visitChance(S, f, guestType, offer = facilityOffer(f)) {
  const likes = (GUEST_LIKES[guestType] || []).includes(f.name);
  const p = (likes ? 0.55 : 0.25) + (S.reputation - 3) * 0.05 + (f.level - 1) * 0.04;
  return Math.min(0.95, Math.max(0, p * priceAppeal(offer, f.level, guestType)));
}

/** Expected walk-in visitors from town: up to a quarter of the seats, more with a good rating. */
export function localDemand(S, f, offer = facilityOffer(f), capacity = facilityCapacity(S, f)) {
  return capacity * 0.25 * (S.reputation / 5) * priceAppeal(offer, f.level, 'Local');
}

/**
 * Expected day for a facility (or a facility type not built yet, at level 1):
 * visitors, guests turned away for lack of seats, revenue, ingredient costs, profit.
 */
export function facilityEstimate(S, facilityOrType, level = 1) {
  const f =
    typeof facilityOrType === 'string'
      ? (() => {
          const ft = FACILITY_TYPES.find((x) => x.type === facilityOrType);
          return ft ? { name: ft.type, level, upkeep: ft.upkeep } : null;
        })()
      : facilityOrType;
  if (!f) return null;
  const offer = facilityOffer(f);
  const capacity = facilityCapacity(S, f);
  let wantGuests = 0;
  for (const g of S.guests || []) wantGuests += visitChance(S, f, g.type, offer);
  const guests = Math.min(capacity, wantGuests);
  const locals = Math.min(capacity - guests, localDemand(S, f, offer, capacity));
  const visitors = guests + locals;
  const avg = (key) => offer.items.reduce((t, i) => t + i[key], 0) / offer.items.length;
  const revenue = visitors * offer.orders * avg('price');
  const cogs = visitors * offer.orders * avg('cost');
  return {
    capacity,
    guests: Math.round(guests),
    locals: Math.round(locals),
    visitors: Math.round(visitors),
    turnedAway: Math.max(0, Math.round(wantGuests - guests)),
    revenue: Math.round(revenue),
    cogs: Math.round(cogs),
    upkeep: f.upkeep,
    income: Math.round(revenue - cogs),
    net: Math.round(revenue - cogs - f.upkeep),
  };
}

/** Roles each facility needs, and which of them the hotel is missing. */
export function missingStaff(S, type) {
  const ft = FACILITY_TYPES.find((f) => f.type === type);
  if (!ft) return [];
  const out = [];
  for (const req of ft.requiredStaff || []) {
    const have = S.staff.filter((s) => s.role === req.role).length;
    if (have < req.count) out.push({ role: req.role, need: req.count - have });
  }
  return out;
}

/** Lower booking chance while the hotel is in debt (service cuts). */
export function debtBookingPenalty(S) {
  return S.money < 0 ? DEBT.bookingPenalty + Math.min(0.3, -S.money / 50000) : 0;
}

/** The asset the bank would seize next: priciest facility, else priciest spare room. */
export function repoTarget(S) {
  let best = null;
  for (const f of S.facilities) {
    if (f.name === 'Lobby') continue;
    const ft = FACILITY_TYPES.find((x) => x.type === f.name);
    const value = ft ? ft.baseCost : 0;
    if (!best || value > best.value) best = { kind: 'facility', id: f.id, name: f.name, value };
  }
  if (best) return best;
  if (S.rooms.length <= 1) return null; // never the last room
  for (const r of S.rooms) {
    const rt = ROOM_TYPES.find((x) => x.type === r.type);
    const value = rt ? rt.baseCost : 0;
    if (!best || value > best.value || (value === best.value && !r.occupied)) best = { kind: 'room', id: r.id, name: `${r.type} room #${r.id}`, value };
  }
  return best;
}

/** Everything the UI needs to explain the hotel's debt. */
export function debtStatus(S) {
  if (S.money >= 0) return { inDebt: false };
  const debt = -S.money;
  const days = (S.stats && S.stats.debtDays) || 0;
  const interest = Math.max(DEBT.minInterest, Math.floor(debt * DEBT.interestRate));
  let repoIn = null;
  if (debt >= DEBT.repoMinDebt) {
    repoIn = days < DEBT.repoAfterDays ? DEBT.repoAfterDays - days : (DEBT.repoEveryDays - ((days - DEBT.repoAfterDays) % DEBT.repoEveryDays)) % DEBT.repoEveryDays || DEBT.repoEveryDays;
  }
  const target = repoTarget(S);
  // Game over comes after DEBT.bankruptAfterDays, or at the next seizure if nothing is left to seize.
  let bankruptIn = DEBT.bankruptAfterDays - days;
  if (!target && repoIn != null) bankruptIn = Math.min(bankruptIn, repoIn);
  return {
    inDebt: true,
    bankruptIn: Math.max(1, bankruptIn),
    debt,
    days,
    interest,
    bookingPenalty: Math.round(debtBookingPenalty(S) * 100),
    repoIn,
    repoTarget: target,
    repoValue: target ? Math.min(debt, Math.round(target.value * DEBT.repoRecovery)) : 0,
    atRiskStaff: S.staff.filter((e) => e.happiness - DEBT.staffMoraleHit <= DEBT.quitBelowMorale).length,
  };
}

/**
 * How far a daily challenge is (progress 0–100) and whether it's won. The day
 * tick uses this to award it; the UI uses it to show live progress. `revenue`
 * is the day's revenue (the UI passes yesterday's as an estimate).
 */
export function evaluateChallenge(S, c, { revenue = 0, startReputation = S.reputation } = {}) {
  let done = false;
  let progress = 0;
  switch (c.id) {
    case 'happy_guests': {
      // FIX: guests have `happiness`, not `satisfaction` (the old check always passed).
      const unhappy = S.guests.filter((g) => g.happiness < 3).length;
      done = S.guests.length > 0 && unhappy === 0;
      progress = S.guests.length ? ((S.guests.length - unhappy) / S.guests.length) * 100 : 0;
      break;
    }
    case 'money_maker':
      progress = Math.min((revenue / c.target) * 100, 100);
      done = revenue >= c.target;
      break;
    case 'full_occupancy': {
      const occ = S.rooms.filter((r) => r.occupied).length;
      progress = S.rooms.length ? (occ / S.rooms.length) * 100 : 0;
      done = S.rooms.length > 0 && occ === S.rooms.length;
      break;
    }
    case 'reputation_boost': {
      const gain = S.reputation - (c.startReputation ?? startReputation);
      progress = Math.max(0, Math.min((gain / c.target) * 100, 100));
      done = gain >= c.target;
      break;
    }
    case 'staff_efficiency': {
      // Every employee in good spirits (4+), not merely "not miserable".
      const happy = S.staff.filter((s) => s.happiness >= 4).length;
      progress = S.staff.length ? (happy / S.staff.length) * 100 : 0;
      done = S.staff.length > 0 && happy === S.staff.length;
      break;
    }
    case 'green_day':
      // Only counts while the hotel is actually running (has guests).
      done = S.guests.length > 0 && S.stats.maintenanceToday === 0;
      progress = done ? 100 : 0;
      break;
    default:
      break;
  }
  return { progress, done };
}

/** Live view of today's challenge for the UI (judged when the next day starts). */
export function challengeStatus(S) {
  const c = S.challenge;
  if (!c) return null;
  const revenue = (S.stats && S.stats.lastDayRevenue) || 0;
  const { progress, done } = evaluateChallenge(S, c, { revenue });
  return { ...c, progress, onTrack: done };
}

// ---------------------------------------------------------------- marketing

/** Campaign price for this hotel: base + per-room fee. */
export function campaignCost(S, id) {
  const c = CAMPAIGNS[id];
  return c ? c.base + c.perRoom * S.rooms.length : null;
}

/** Arrival multiplier from running campaigns (each extra campaign adds a bit less). */
export function marketingDemand(S) {
  const active = (S.marketingCampaigns || []).filter((c) => c.active);
  const stacking = Math.max(0.5, 1 - active.length * 0.1);
  return 1 + active.reduce((t, c) => t + ((CAMPAIGNS[c.id] && CAMPAIGNS[c.id].demand) || 0), 0) * stacking;
}

/** Marketing brings guests, not rooms: warn when the hotel is already nearly full. */
export function marketingAdvice(S) {
  const e = economics(S);
  if (e.usableRooms && e.occupancy >= 0.9) return { full: true, text: `Your rooms are ${Math.round(e.occupancy * 100)}% full. Marketing can't fill rooms you don't have — build more first.` };
  return { full: false, text: '' };
}

// ---------------------------------------------------------------- insurance

/** The hotel's insurance plan id ('none' | 'basic' | 'full'). */
export function insurancePlan(S) {
  return S.insurance && INSURANCE_PLANS[S.insurance] ? S.insurance : 'none';
}

/** Daily premium for a plan (the current one by default). */
export function insurancePremium(S, plan = insurancePlan(S)) {
  const p = INSURANCE_PLANS[plan];
  return p.base + p.perRoom * S.rooms.length;
}

/**
 * Most cash one disaster can cost you under a plan: `deductibleDays` of
 * business (the bigger of revenue and running costs), at least `min`.
 * null = not insured, you pay everything.
 */
export function insuranceCap(S, plan = insurancePlan(S)) {
  const p = INSURANCE_PLANS[plan];
  if (!p.deductibleDays) return null;
  const revenue = (S.stats && S.stats.lastDayRevenue) || 0;
  const staff = S.staff.reduce((t, e) => t + e.salary, 0);
  const upkeep = S.facilities.reduce((t, f) => t + f.upkeep, 0) + S.rooms.length * 30;
  return Math.max(p.min, Math.round(p.deductibleDays * Math.max(revenue, staff + upkeep)));
}
